DROP TABLE IF EXISTS `crm_fournisseur`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `crm_fournisseur` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_agence` int(11) DEFAULT NULL,
  `source` varchar(100) DEFAULT NULL,
  `titre` varchar(10) DEFAULT NULL,
  `prenom` varchar(100) DEFAULT NULL,
  `nom` varchar(100) DEFAULT NULL,
  `raison_social` varchar(100) DEFAULT NULL,
  `ice` varchar(50) DEFAULT NULL,
  `tel` varchar(50) DEFAULT NULL,
  `tel2` varchar(50) DEFAULT NULL,
  `tel3` varchar(50) DEFAULT NULL,
  `email` varchar(250) DEFAULT NULL,
  `password` varchar(250) DEFAULT NULL,
  `cp` varchar(50) DEFAULT NULL,
  `adresse` varchar(250) DEFAULT NULL,
  `adresse2` varchar(250) DEFAULT NULL,
  `ville` varchar(100) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `categorie` int(11) DEFAULT NULL,
  `lien` varchar(500) DEFAULT NULL,
  `pays` varchar(100) DEFAULT NULL,
  `photo` varchar(250) DEFAULT NULL,
  `doc` varchar(250) DEFAULT NULL,
  `active` int(3) DEFAULT NULL,
  `valide` int(11) DEFAULT NULL,
  `user_add` int(11) DEFAULT NULL,
  `user_edit` int(11) DEFAULT NULL,
  `date_add` date DEFAULT NULL,
  `last_edit` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

