DROP TABLE IF EXISTS `crm_resourcehumaine`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `crm_resourcehumaine` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reference` varchar(100) DEFAULT NULL,
  `reference_pointage` varchar(255) DEFAULT NULL,
  `id_agency` int(11) NOT NULL,
  `cin` varchar(100) DEFAULT NULL,
  `firstname` varchar(100) DEFAULT NULL,
  `lastname` varchar(100) DEFAULT NULL,
  `email` varchar(250) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `second_phone` varchar(255) DEFAULT NULL,
  `address` varchar(250) DEFAULT NULL,
  `city` varchar(50) DEFAULT NULL,
  `prospecting_source` varchar(255) DEFAULT NULL,
  `rib` varchar(255) DEFAULT NULL,
  `salaire_initial` decimal(10,2) DEFAULT NULL,
  `salaire_actuel` decimal(10,2) DEFAULT NULL,
  `commission_parrainage` decimal(10,2) NOT NULL DEFAULT 0.00,
  `cnss_number` varchar(255) DEFAULT NULL,
  `function` varchar(250) DEFAULT NULL,
  `id_profil` int(11) DEFAULT NULL,
  `status` varchar(250) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `contract_signing_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `photo` varchar(250) DEFAULT NULL,
  `remark` mediumtext DEFAULT NULL,
  `active` int(11) NOT NULL DEFAULT 0,
  `last_document_reminder` date DEFAULT NULL,
  `date_add` date DEFAULT NULL,
  `last_edit` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
