CREATE TABLE `hwd_facture` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_facture` int(11) DEFAULT NULL,
  `numero` varchar(20) DEFAULT NULL,
  `sec_numero` varchar(20) DEFAULT NULL,
  `id_client` int(11) DEFAULT NULL,
  `id_devis` int(11) DEFAULT NULL,
  `date_facture` date DEFAULT NULL,
  `total` double DEFAULT NULL,
  `statu` int(3) DEFAULT NULL,
  `devise` varchar(10) DEFAULT NULL,
  `discount` varchar(20) DEFAULT NULL,
  `discount_val` double DEFAULT NULL,
  `condition_paiment` mediumtext DEFAULT NULL,
  `remarque` mediumtext DEFAULT NULL,
  `proforma` int(11) DEFAULT NULL,
  `langue` varchar(5) DEFAULT NULL,
  `avoir` int(11) DEFAULT NULL,
  `archived` int(11) DEFAULT NULL,
  `date_add` date DEFAULT NULL,
  `last_edit` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
